def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_def = 0
    my_def = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_def += 1
        if history[i][0] == 'D':
            my_def += 1
    if opp_def == n:
        return 'D'
    if opp_def == 0:
        return 'C'
    last_mine, last_opp = history[-1]
    if n >= 2:
        if history[-1][0] == 'D' and history[-1][1] == 'D' and history[-2][0] == 'D' and history[-2][1] == 'D':
            return 'C'
        if last_mine == 'C' and last_opp == 'D' and history[-2][0] == 'D' and history[-2][1] == 'C':
            return 'C'
    if last_opp == 'D':
        if my_def > opp_def + 2 and opp_def < n // 2:
            return 'C'
        return 'D'
    return 'C'
